{"command":"cat << 'EOF' > test_jpeg.c
#include <stdio.h>
#include <stdlib.h>
#include <dlfcn.h>
#include <setjmp.h>

struct dummy_error_mgr {
    void *error_exit;
    void *emit_message;
    void *output_message;
    void *format_message;
    void *reset_error_mgr;
    int msg_code;
    union {
        int i[8];
        char s[80];
    } msg_parm;
    int trace_level;
    long num_warnings;
    const char **jpeg_message_table;
    int last_jpeg_message;
    void *addon_message_table;
    int first_addon_message;
    int last_addon_message;
};

struct my_error_mgr {
    struct dummy_error_mgr pub;
    jmp_buf setjmp_buffer;
};

void my_error_exit(struct my_error_mgr *err) {
    longjmp(err->setjmp_buffer, 1);
}

int main() {
    void *handle = dlopen("libjpeg.so.8", RTLD_LAZY);
    if (!handle) {
        printf("Cannot load libjpeg\n");
        return 1;
    }

    void (*jpeg_std_error)(void *) = dlsym(handle, "jpeg_std_error");
    void (*jpeg_CreateDecompress)(void *, int, size_t) = dlsym(handle, "jpeg_CreateDecompress");
    void (*jpeg_destroy_decompress)(void *) = dlsym(handle, "jpeg_destroy_decompress");

    struct my_error_mgr jerr;
    jpeg_std_error(&jerr.pub);
    jerr.pub.error_exit = my_error_exit;

    int correct_size = -1;
    for (size_t sz = 1; sz < 2000; sz++) {
        void *cinfo = calloc(1, sz);
        ((void**)cinfo)[0] = &jerr; // cinfo->err is the first field!

        if (setjmp(jerr.setjmp_buffer)) {
            // failed
            free(cinfo);
            continue;
        }

        jpeg_CreateDecompress(cinfo, 80, sz);
        correct_size = sz;
        jpeg_destroy_decompress(cinfo);
        free(cinfo);
        break;
    }

    printf("Correct size: %d\n", correct_size);
    return 0;
}
EOF
gcc test_jpeg.c -ldl -o test_jpeg && ./test_jpeg
"}

