{"command":"cat << 'EOF' > test_jpeg.c
#include <stdio.h>
#include <stdlib.h>
#include <dlfcn.h>
#include <setjmp.h>
#include <string.h>

typedef unsigned int JDIMENSION;
typedef int J_COLOR_SPACE;
typedef int J_DCT_METHOD;
typedef int J_DITHER_MODE;
typedef int boolean;

struct my_jpeg_decompress_struct {
  void * err;
  void * mem;
  void * progress;
  void *client_data;
  boolean is_decompressor;
  int global_state;

  void * src;

  JDIMENSION image_width;
  JDIMENSION image_height;
  int num_components;
  J_COLOR_SPACE jpeg_color_space;

  J_COLOR_SPACE out_color_space;
  unsigned int scale_num, scale_denom;
  double output_gamma;
  boolean buffered_image;
  boolean raw_data_out;
  J_DCT_METHOD dct_method;
  boolean do_fancy_upsampling;
  boolean do_block_smoothing;
  boolean quantize_colors;
  J_DITHER_MODE dither_mode;
  boolean two_pass_quantize;
  int desired_number_of_colors;
  boolean enable_1pass_quant;
  boolean enable_external_quant;
  boolean enable_2pass_quant;

  JDIMENSION output_width;
  JDIMENSION output_height;
  int out_color_components;
  int output_components;

  char pad[1000];
};

struct my_error_mgr {
    char pub[1024];
    jmp_buf setjmp_buffer;
};

void my_error_exit(void *cinfo) {
    void **cinfo_ptr = (void**)cinfo;
    struct my_error_mgr *err = (struct my_error_mgr *)cinfo_ptr[0];
    longjmp(err->setjmp_buffer, 1);
}

int main(int argc, char **argv) {
    if (argc < 2) return 1;
    void *handle = dlopen("libjpeg.so.8", RTLD_LAZY);

    void (*jpeg_std_error)(void *) = dlsym(handle, "jpeg_std_error");
    void (*jpeg_CreateDecompress)(void *, int, size_t) = dlsym(handle, "jpeg_CreateDecompress");
    void (*jpeg_stdio_src)(void *, FILE *) = dlsym(handle, "jpeg_stdio_src");
    int (*jpeg_read_header)(void *, boolean) = dlsym(handle, "jpeg_read_header");
    boolean (*jpeg_start_decompress)(void *) = dlsym(handle, "jpeg_start_decompress");

    struct my_error_mgr jerr;
    memset(&jerr, 0, sizeof(jerr));
    jpeg_std_error(&jerr.pub);

    void **pub_ptr = (void**)&jerr.pub;
    pub_ptr[0] = my_error_exit;

    struct my_jpeg_decompress_struct *cinfo = calloc(1, 656);
    cinfo->err = &jerr;

    if (setjmp(jerr.setjmp_buffer)) {
        printf("JPEG error\n");
        return 1;
    }

    jpeg_CreateDecompress(cinfo, 80, 656);

    FILE *f = fopen(argv[1], "rb");
    jpeg_stdio_src(cinfo, f);
    jpeg_read_header(cinfo, 1);
    jpeg_start_decompress(cinfo);

    printf("Image: %u x %u, out: %u x %u, components: %d\n", 
           cinfo->image_width, cinfo->image_height, 
           cinfo->output_width, cinfo->output_height, 
           cinfo->output_components);

    return 0;
}
EOF
gcc test_jpeg.c -ldl -o test_jpeg && ./test_jpeg test.jpg
"}

