#include <stdlib.h>
#include <dlfcn.h>
#include <setjmp.h>
#include <string.h>

typedef unsigned int JDIMENSION;
typedef int J_COLOR_SPACE;
typedef int boolean;

struct my_jpeg_compress_struct {
  void * err;
  void * mem;
  void * progress;
  void *client_data;
  boolean is_decompressor;
  int global_state;
  void * dest;

  JDIMENSION image_width;
  JDIMENSION image_height;
  int input_components;
  int in_color_space;

  double input_gamma;

  // padding to reach the end
  char pad[1000];
};

struct my_error_mgr {
    char pub[1024];
    jmp_buf setjmp_buffer;
};

void my_error_exit(void *cinfo) {
    void **cinfo_ptr = (void**)cinfo;
    struct my_error_mgr *err = (struct my_error_mgr *)cinfo_ptr[0];
    longjmp(err->setjmp_buffer, 1);
}

int main(int argc, char **argv) {
    void *handle = dlopen("libjpeg.so.8", RTLD_LAZY);

    void (*jpeg_std_error)(void *) = dlsym(handle, "jpeg_std_error");
    void (*jpeg_CreateCompress)(void *, int, size_t) = dlsym(handle, "jpeg_CreateCompress");
    void (*jpeg_stdio_dest)(void *, FILE *) = dlsym(handle, "jpeg_stdio_dest");
    void (*jpeg_set_defaults)(void *) = dlsym(handle, "jpeg_set_defaults");
    void (*jpeg_set_quality)(void *, int, boolean) = dlsym(handle, "jpeg_set_quality");
    void (*jpeg_start_compress)(void *, boolean) = dlsym(handle, "jpeg_start_compress");
    unsigned int (*jpeg_write_scanlines)(void *, unsigned char **, unsigned int) = dlsym(handle, "jpeg_write_scanlines");
    void (*jpeg_finish_compress)(void *) = dlsym(handle, "jpeg_finish_compress");
    void (*jpeg_destroy_compress)(void *) = dlsym(handle, "jpeg_destroy_compress");

    struct my_error_mgr jerr;
    memset(&jerr, 0, sizeof(jerr));
    jpeg_std_error(&jerr.pub);

    void **pub_ptr = (void**)&jerr.pub;
    pub_ptr[0] = my_error_exit;

    // Size of jpeg_compress_struct is usually slightly smaller or larger. 
    // Let's guess 1024 bytes and let it pass if libjpeg checks it?
    // Wait, jpeg_CreateCompress checks size too!
    // We must find correct size for compress!
    int correct_sz = -1;
    for(int sz=16; sz<2000; sz++) {
        void *cinfo = calloc(1, sz);
        ((void**)cinfo)[0] = &jerr;
        if (!setjmp(jerr.setjmp_buffer)) {
            jpeg_CreateCompress(cinfo, 80, sz);
            correct_sz = sz;
            jpeg_destroy_compress(cinfo);
            free(cinfo);
            break;
        }
        free(cinfo);
    }

    if (correct_sz == -1) { printf("Failed to find size\n"); return 1; }

    struct my_jpeg_compress_struct *cinfo = calloc(1, correct_sz);
    cinfo->err = &jerr;
    jpeg_CreateCompress(cinfo, 80, correct_sz);

    FILE *f = fopen("valid.jpg", "wb");
    jpeg_stdio_dest(cinfo, f);

    cinfo->image_width = 256;
    cinfo->image_height = 256;
    cinfo->input_components = 3;
    cinfo->in_color_space = 2; // JCS_RGB

    jpeg_set_defaults(cinfo);
    jpeg_set_quality(cinfo, 90, 1);
    jpeg_start_compress(cinfo, 1);

    unsigned char *row = malloc(256 * 3);
    for (int y = 0; y < 256; y++) {
        for (int x = 0; x < 256; x++) {
            row[x*3 + 0] = x; // Gradient black to white (R)
            row[x*3 + 1] = x; // (G)
            row[x*3 + 2] = x; // (B)
        }
        unsigned char *row_ptr[1] = { row };
        jpeg_write_scanlines(cinfo, row_ptr, 1);
    }

    jpeg_finish_compress(cinfo);
    jpeg_destroy_compress(cinfo);
    fclose(f);
    free(row);
    free(cinfo);
    return 0;
}
EOF
gcc write_jpeg.c -ldl -o write_jpeg && ./write_jpeg
ls -l valid.jpg
"}

