    for (int y = 0; y < cinfo->output_height; y++) {
        unsigned char *row_ptr[1] = { row };
        jpeg_read_scanlines(cinfo, row_ptr, 1);
        if (y == 8 || y == 24) {
            printf("Row %d: ", y);
            for (int x = 0; x < 10; x++) {
