                int R = row[src_x * 3 + 0];
                int G = row[src_x * 3 + 1];
                int B = row[src_x * 3 + 2];
                int color = 30;
                if (R > 127) color += 1;
                if (G > 127) color += 2;
                if (B > 127) color += 4;
                printf("%d ", color);
            }
            printf("\n");
        }
    }
    return 0;
}
