{"command":"cat << 'EOF' > main.c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <curl/curl.h>
#include <jpeglib.h>
#include <setjmp.h>

const char *default_chars = "   ...',;:clodxkO0KXNWM";

struct error_mgr {
    struct jpeg_error_mgr pub;
    jmp_buf setjmp_buffer;
};

void my_error_exit(j_common_ptr cinfo) {
    struct error_mgr *err = (struct error_mgr *)cinfo->err;
    longjmp(err->setjmp_buffer, 1);
}

int get_term_width() {
    struct winsize w;
    if (ioctl(STDOUT_FILENO, TIOCGWINSZ, &w) != -1 && w.ws_col > 0) return w.ws_col;
    char *col_str = getenv("COLUMNS");
    if (col_str) return atoi(col_str);
    return 80;
}

int get_term_height() {
    struct winsize w;
    if (ioctl(STDOUT_FILENO, TIOCGWINSZ, &w) != -1 && w.ws_row > 0) return w.ws_row;
    char *row_str = getenv("LINES");
    if (row_str) return atoi(row_str);
    return 24;
}

int map_rgb_to_ansi(int r, int g, int b) {
    int colors[8][3] = {
        {0,0,0}, {255,0,0}, {0,255,0}, {255,255,0},
        {0,0,255}, {255,0,255}, {0,255,255}, {255,255,255}
    };
    int best = 0, min_dist = 1000000;
    for(int i=0; i<8; i++) {
        int dist = (r-colors[i][0])*(r-colors[i][0]) + 
                   (g-colors[i][1])*(g-colors[i][1]) + 
                   (b-colors[i][2])*(b-colors[i][2]);
        if(dist < min_dist) { min_dist = dist; best = i; }
    }
    return 30 + best;
}

void process_image(FILE *f, int req_w, int req_h, int term_fit, int term_zoom, 
                   int border, int invert, int colors, int html,
                   double rw, double gw, double bw, const char *chars) {
    struct jpeg_decompress_struct cinfo;
    struct error_mgr jerr;
    cinfo.err = jpeg_std_error(&jerr.pub);
    jerr.pub.error_exit = my_error_exit;
    if (setjmp(jerr.setjmp_buffer)) {
        jpeg_destroy_decompress(&cinfo);
        return;
    }
    jpeg_create_decompress(&cinfo);
    jpeg_stdio_src(&cinfo, f);
    jpeg_read_header(&cinfo, TRUE);
    cinfo.out_color_space = JCS_RGB;

    if (term_zoom) {
        req_w = get_term_width();
        req_h = get_term_height();
    } else if (term_fit || (req_w == 0 && req_h == 0)) {
        int tw = get_term_width();
        int th = get_term_height() - 1; // Leave 1 for prompt
        double img_aspect = (double)cinfo.image_width / (cinfo.image_height * 2.0);
        double term_aspect = (double)tw / th;
        if (img_aspect > term_aspect) {
            req_w = tw;
            req_h = req_w / (img_aspect * 2.0);
            if (req_h == 0) req_h = 1;
        } else {
            req_h = th;
            req_w = req_h * (img_aspect * 2.0);
            if (req_w == 0) req_w = 1;
        }
    } else if (req_h == 0 && req_w > 0) {
        req_h = (req_w * cinfo.image_height) / (cinfo.image_width * 2);
        if (req_h == 0) req_h = 1;
    } else if (req_w == 0 && req_h > 0) {
        req_w = (req_h * cinfo.image_width * 2) / cinfo.image_height;
        if (req_w == 0) req_w = 1;
    }

    if (border) { req_w -= 2; req_h -= 2; }
    if (req_w < 1) req_w = 1;
    if (req_h < 1) req_h = 1;

    cinfo.scale_num = req_w;
    cinfo.scale_denom = cinfo.image_width;
    jpeg_calc_output_dimensions(&cinfo);
    jpeg_start_decompress(&cinfo);

    int row_stride = cinfo.output_width * cinfo.output_components;
    unsigned char **buffer = malloc(cinfo.output_height * sizeof(unsigned char *));
    for (int i = 0; i < cinfo.output_height; i++) {
        buffer[i] = malloc(row_stride);
    }
    int y = 0;
    while (cinfo.output_scanline < cinfo.output_height) {
        jpeg_read_scanlines(&cinfo, &buffer[y], 1);
        y++;
    }

    int clen = strlen(chars);
    if (html) {
        printf("<?xml version='1.0' encoding='ISO-8859-1'?>\n"
               "<!DOCTYPE html PUBLIC '-//W3C//DTD XHTML 1.0 Strict//EN'  'http://www.w3.org/TR/xhtml1/DTD/xhtml1-strict.dtd'>\n"
               "<html xmlns='http://www.w3.org/1999/xhtml' lang='en' xml:lang='en'>\n"
               "<head>\n<title>jp2a converted image</title>\n<style type='text/css'>\n"
               "body { background-color: black; }\n"
               ".ascii { font-family: Courier; color: white; font-size:8pt; font-weight: bold; }\n"
               "</style>\n</head>\n<body>\n<div class='ascii'><pre>\n");
    }

    if (border && !html) {
        printf("+"); for(int i=0; i<req_w; i++) printf("-"); printf("+\n");
    }

    for (int dy = 0; y > 0 && dy < req_h; dy++) {
        if (border && !html) printf("|");
        int last_color = -1;
        for (int dx = 0; dx < req_w; dx++) {
            int src_x = (int)((dx + 0.5) * cinfo.output_width / req_w);
            int src_y = (int)((dy + 0.5) * cinfo.output_height / req_h);
            if (src_x >= cinfo.output_width) src_x = cinfo.output_width - 1;
            if (src_y >= cinfo.output_height) src_y = cinfo.output_height - 1;

            unsigned char *p = buffer[src_y] + src_x * 3;
            int r = p[0], g = p[1], b = p[2];
            double L = rw * r + gw * g + bw * b;
            int idx = (int)(L * clen / 256.0);
            if (idx >= clen) idx = clen - 1;
            if (invert) idx = clen - 1 - idx;
            char ch = chars[idx];

            if (colors && !html) {
                int c = map_rgb_to_ansi(r, g, b);
                if (c != last_color) {
                    if (c == 37) printf("\033[0m"); // reset for white/default?
                    else printf("\033[%dm", c);
                    last_color = c;
                }
                printf("%c", ch);
            } else {
                printf("%c", ch);
            }
        }
        if (colors && last_color != -1 && !html) printf("\033[0m");
        if (border && !html) printf("|");
        printf("\n");
    }

    if (border && !html) {
        printf("+"); for(int i=0; i<req_w; i++) printf("-"); printf("+\n");
    }
    if (html) {
        printf("</pre>\n</div>\n</body>\n</html>\n");
    }

    for (int i = 0; i < cinfo.output_height; i++) free(buffer[i]);
    free(buffer);
    jpeg_finish_decompress(&cinfo);
    jpeg_destroy_decompress(&cinfo);
}

size_t curl_write_data(void *ptr, size_t size, size_t nmemb, FILE *stream) {
    size_t written = fwrite(ptr, size, nmemb, stream);
    return written;
}

int main(int argc, char **argv) {
    int req_w = 0, req_h = 0, term_fit = 0, term_zoom = 0;
    int border = 0, invert = 0, colors = 0, html = 0;
    double rw = 0.2989, gw = 0.5866, bw = 0.1145;
    const char *chars = default_chars;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--version") == 0 || strcmp(argv[i], "-V") == 0) {
            printf("jp2a 1.0.8\nCopyright 2006-2016 Christian Stigen Larsen\nDistributed under the GNU General Public License (GPL) v2.\n\nUsage: jp2a [ options ] [ file(s) | URL(s) ]\n");
            return 0;
        } else if (strcmp(argv[i], "--help") == 0 || strcmp(argv[i], "-h") == 0) {
            printf("jp2a 1.0.8\nUsage: jp2a [ options ] [ file(s) | URL(s) ]\n");
            return 0;
        } else if (strncmp(argv[i], "--size=", 7) == 0) {
            sscanf(argv[i]+7, "%dx%d", &req_w, &req_h);
        } else if (strncmp(argv[i], "--width=", 8) == 0) {
            req_w = atoi(argv[i]+8);
        } else if (strncmp(argv[i], "--height=", 9) == 0) {
            req_h = atoi(argv[i]+9);
        } else if (strcmp(argv[i], "--term-fit") == 0 || strcmp(argv[i], "-f") == 0) {
            term_fit = 1;
        } else if (strcmp(argv[i], "--term-zoom") == 0 || strcmp(argv[i], "-z") == 0) {
            term_zoom = 1;
