    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--version") == 0 || strcmp(argv[i], "-V") == 0) {
            printf("jp2a 1.0.8\nCopyright 2006-2016 Christian Stigen Larsen\nDistributed under the GNU General Public License (GPL) v2.\n\nUsage: jp2a [ options ] [ file(s) | URL(s) ]\n\nConvert files or URLs from JPEG format to ASCII.\n");
            return 0;
        } else if (strcmp(argv[i], "--help") == 0 || strcmp(argv[i], "-h") == 0) {
            printf("jp2a 1.0.8\nCopyright 2006-2016 Christian Stigen Larsen\nDistributed under the GNU General Public License (GPL) v2.\n\nUsage: jp2a [ options ] [ file(s) | URL(s) ]\n\nConvert files or URLs from JPEG format to ASCII.\n");
            return 0;
        } else if (strncmp(argv[i], "--size=", 7) == 0) {
            sscanf(argv[i]+7, "%dx%d", &req_w, &req_h);
            term_fit = 0;
        } else if (strncmp(argv[i], "--width=", 8) == 0) {
            req_w = atoi(argv[i]+8);
            term_fit = 0;
        } else if (strncmp(argv[i], "--height=", 9) == 0) {
            req_h = atoi(argv[i]+9);
            term_fit = 0;
        } else if (strcmp(argv[i], "--term-fit") == 0 || strcmp(argv[i], "-f") == 0) {
            term_fit = 1;
        } else if (strcmp(argv[i], "--term-zoom") == 0 || strcmp(argv[i], "-z") == 0) {
            term_zoom = 1; term_fit = 0;
        } else if (strcmp(argv[i], "--border") == 0 || strcmp(argv[i], "-b") == 0) {
            border = 1;
        } else if (strcmp(argv[i], "--invert") == 0 || strcmp(argv[i], "-i") == 0) {
            invert = 1;
        } else if (strcmp(argv[i], "--background=light") == 0) {
            invert = 0;
        } else if (strcmp(argv[i], "--background=dark") == 0) {
            invert = 1;
        } else if (strcmp(argv[i], "--colors") == 0) {
            colors = 1;
        } else if (strcmp(argv[i], "--html") == 0) {
            html = 1;
        } else if (strncmp(argv[i], "--chars=", 8) == 0) {
            chars = argv[i]+8;
        } else if (strncmp(argv[i], "--red=", 6) == 0) {
            rw = atof(argv[i]+6);
        } else if (strncmp(argv[i], "--green=", 8) == 0) {
            gw = atof(argv[i]+8);
        } else if (strncmp(argv[i], "--blue=", 7) == 0) {
            bw = atof(argv[i]+7);
        } else if (strcmp(argv[i], "--flipx") == 0 || strcmp(argv[i], "-x") == 0) {
            flipx = 1;
        } else if (strcmp(argv[i], "--flipy") == 0 || strcmp(argv[i], "-y") == 0) {
            flipy = 1;
        } else if (strcmp(argv[i], "--term-width") == 0) {
            term_w_flag = 1;
        } else if (strcmp(argv[i], "--term-height") == 0) {
            term_h_flag = 1;
        } else if (strcmp(argv[i], "-") == 0) {
            process_image(stdin, req_w, req_h, term_fit, term_zoom, border, invert, colors, html, rw, gw, bw, chars, term_w_flag, term_h_flag, flipx, flipy);
        } else if (argv[i][0] != '-') {
            FILE *f = NULL;
            if (strncmp(argv[i], "http://", 7) == 0 || strncmp(argv[i], "https://", 8) == 0) {
                f = tmpfile();
                if(f) {
                    CURL *curl = curl_easy_init();
                    if(curl) {
                        curl_easy_setopt(curl, CURLOPT_URL, argv[i]);
                        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, fwrite);
                        curl_easy_setopt(curl, CURLOPT_WRITEDATA, f);
                        curl_easy_perform(curl);
                        curl_easy_cleanup(curl);
                    }
                    rewind(f);
                }
            } else {
                f = fopen(argv[i], "rb");
            }
            if (f) {
                process_image(f, req_w, req_h, term_fit, term_zoom, border, invert, colors, html, rw, gw, bw, chars, term_w_flag, term_h_flag, flipx, flipy);
                fclose(f);
            }
        }
    }
    return 0;
}
