void init_jpeg() {
    lj_handle = dlopen("libjpeg.so.8", RTLD_LAZY);
    if(!lj_handle) lj_handle = dlopen("libjpeg.so.62", RTLD_LAZY);
    if(!lj_handle) { printf("Cannot load libjpeg\n"); exit(1); }
    j_std_error = dlsym(lj_handle, "jpeg_std_error");
    j_CreateDecompress = dlsym(lj_handle, "jpeg_CreateDecompress");
    j_stdio_src = dlsym(lj_handle, "jpeg_stdio_src");
    j_read_header = dlsym(lj_handle, "jpeg_read_header");
    j_calc_output_dimensions = dlsym(lj_handle, "jpeg_calc_output_dimensions");
    j_start_decompress = dlsym(lj_handle, "jpeg_start_decompress");
    j_read_scanlines = dlsym(lj_handle, "jpeg_read_scanlines");
    j_finish_decompress = dlsym(lj_handle, "jpeg_finish_decompress");
