    char *row_str = getenv("LINES");
    if (row_str) return atoi(row_str);
    return 24;
}

int map_rgb_to_ansi(int r, int g, int b) {
    int max = r;
    if (g > max) max = g;
    if (b > max) max = b;
    int thresh = (int)(max * 0.8);
    int c = 30;
    if (r >= thresh && r > 0) c += 1;
    if (g >= thresh && g > 0) c += 2;
    if (b >= thresh && b > 0) c += 4;
    return c;
}

void process_image(FILE *f, int req_w, int req_h, int term_fit, int term_zoom, 
                   int border, int invert, int colors, int html,
                   double rw, double gw, double bw, const char *chars,
                   int term_w_flag, int term_h_flag, int flipx, int flipy) {
    struct my_jpeg_decompress_struct *cinfo = calloc(1, 656);
    struct error_mgr jerr;
    memset(&jerr, 0, sizeof(jerr));
    j_std_error(&jerr.pub);
    ((void**)&jerr.pub)[0] = my_error_exit;
    cinfo->err = &jerr;

    if (setjmp(jerr.setjmp_buffer)) {
        j_destroy_decompress(cinfo);
        free(cinfo);
        return;
    }
    j_CreateDecompress(cinfo, 80, 656);
    j_stdio_src(cinfo, f);
    j_read_header(cinfo, 1);
    cinfo->out_color_space = JCS_RGB;

    if (term_zoom) {
        req_w = get_term_width(term_w_flag);
        req_h = get_term_height(term_h_flag);
    } else if (term_fit || (req_w == 0 && req_h == 0)) {
        int tw = get_term_width(term_w_flag);
        int th = get_term_height(term_h_flag) - 1;
        double img_aspect = (double)cinfo->image_width / ((double)cinfo->image_height * 2.0);
        double term_aspect = (double)tw / (double)th;
        if (img_aspect > term_aspect) {
            req_w = tw;
            req_h = (int)(req_w / (img_aspect * 2.0));
            if (req_h == 0) req_h = 1;
        } else {
            req_h = th;
            req_w = (int)(req_h * (img_aspect * 2.0));
            if (req_w == 0) req_w = 1;
        }
    } else if (req_h == 0 && req_w > 0) {
        req_h = (int)((req_w * cinfo->image_height) / (cinfo->image_width * 2.0));
        if (req_h == 0) req_h = 1;
    } else if (req_w == 0 && req_h > 0) {
        req_w = (int)((req_h * cinfo->image_width * 2.0) / cinfo->image_height);
        if (req_w == 0) req_w = 1;
    }

    if (border) { req_w -= 2; req_h -= 2; }
    if (req_w < 1) req_w = 1;
    if (req_h < 1) req_h = 1;

    cinfo->scale_num = req_w;
    cinfo->scale_denom = cinfo->image_width;
    j_calc_output_dimensions(cinfo);
    j_start_decompress(cinfo);

    int row_stride = cinfo->output_width * cinfo->output_components;
    unsigned char **buffer = malloc(cinfo->output_height * sizeof(unsigned char *));
    for (int i = 0; i < (int)cinfo->output_height; i++) {
        buffer[i] = malloc(row_stride);
    }
    int y = 0;
    while (y < (int)cinfo->output_height) {
        j_read_scanlines(cinfo, &buffer[y], 1);
        y++;
    }

    int clen = strlen(chars);
    if (html) {
        printf("<?xml version='1.0' encoding='ISO-8859-1'?>\n"
               "<!DOCTYPE html PUBLIC '-//W3C//DTD XHTML 1.0 Strict//EN'  'http://www.w3.org/TR/xhtml1/DTD/xhtml1-strict.dtd'>\n"
               "<html xmlns='http://www.w3.org/1999/xhtml' lang='en' xml:lang='en'>\n"
               "<head>\n<title>jp2a converted image</title>\n<style type='text/css'>\n"
               "body { background-color: black; }\n"
               ".ascii { font-family: Courier; color: white; font-size:8pt; font-weight: bold; }\n"
               "</style>\n</head>\n<body>\n<div class='ascii'><pre>\n");
    }

    if (border && !html) {
        printf("+"); for(int i=0; i<req_w; i++) printf("-"); printf("+\n");
    }

    for (int dy = 0; dy < req_h; dy++) {
        if (border && !html) printf("|");
        int last_color = -1;
        int act_dy = flipy ? (req_h - 1 - dy) : dy;
        for (int dx = 0; dx < req_w; dx++) {
            int act_dx = flipx ? (req_w - 1 - dx) : dx;
            int src_x = (int)((act_dx + 0.5) * cinfo->output_width / req_w);
            int src_y = (int)((act_dy + 0.5) * cinfo->output_height / req_h);
            if (src_x >= (int)cinfo->output_width) src_x = cinfo->output_width - 1;
            if (src_y >= (int)cinfo->output_height) src_y = cinfo->output_height - 1;

            unsigned char *p = buffer[src_y] + src_x * 3;
            int r = p[0], g = p[1], b = p[2];
            double L = rw * r + gw * g + bw * b;
            int idx = (int)(L * clen / 256.0);
            if (idx >= clen) idx = clen - 1;
            int final_idx = invert ? (clen - 1 - idx) : idx;
            char ch = chars[final_idx];

            if (colors && !html) {
                int c = map_rgb_to_ansi(r, g, b);
                if (c != last_color) {
                    printf("\033[%dm", c);
                    last_color = c;
                }
                printf("%c", ch);
            } else {
                printf("%c", ch);
            }
        }
        if (colors && last_color != -1 && !html) printf("\033[0m");
        if (border && !html) printf("|");
        printf("\n");
    }

    if (border && !html) {
        printf("+"); for(int i=0; i<req_w; i++) printf("-"); printf("+\n");
    }
    if (html) {
        printf("</pre>\n</div>\n</body>\n</html>\n");
    }

    for (int i = 0; i < (int)cinfo->output_height; i++) free(buffer[i]);
    free(buffer);
    j_finish_decompress(cinfo);
    j_destroy_decompress(cinfo);
    free(cinfo);
}

size_t curl_write_data(void *ptr, size_t size, size_t nmemb, FILE *stream) {
    return fwrite(ptr, size, nmemb, stream);
}

int main(int argc, char **argv) {
    if (argc == 1) {
        printf("jp2a 1.0.8\nUsage: jp2a [ options ] [ file(s) | URL(s) ]\n");
        return 0;
    }

    init_jpeg();

    void *lc_handle = dlopen("libcurl.so.4", RTLD_LAZY);
    void *(*c_easy_init)(void) = NULL;
    int (*c_easy_setopt)(void*, int, ...) = NULL;
    int (*c_easy_perform)(void*) = NULL;
    void (*c_easy_cleanup)(void*) = NULL;

    if (lc_handle) {
        c_easy_init = dlsym(lc_handle, "curl_easy_init");
        c_easy_setopt = dlsym(lc_handle, "curl_easy_setopt");
        c_easy_perform = dlsym(lc_handle, "curl_easy_perform");
        c_easy_cleanup = dlsym(lc_handle, "curl_easy_cleanup");
    }

    int req_w = 0, req_h = 0, term_fit = 1, term_zoom = 0;
    int border = 0, invert = 0, colors = 0, html = 0;
    double rw = 0.2989, gw = 0.5866, bw = 0.1145;
    const char *chars = default_chars;
    int term_w_flag = 0, term_h_flag = 0, flipx = 0, flipy = 0;

    for (int i = 1; i < argc; i++) {
        if (strncmp(argv[i], "--output=", 9) == 0) {
            if (strcmp(argv[i]+9, "-") != 0) freopen(argv[i]+9, "w", stdout);
        }
    }

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--version") == 0 || strcmp(argv[i], "-V") == 0) {
            printf("jp2a 1.0.8\nCopyright 2006-2016 Christian Stigen Larsen\nDistributed under the GNU General Public License (GPL) v2.\n\nUsage: jp2a [ options ] [ file(s) | URL(s) ]\n\nConvert files or URLs from JPEG format to ASCII.\n");
            return 0;
        } else if (strcmp(argv[i], "--help") == 0 || strcmp(argv[i], "-h") == 0) {
            printf("jp2a 1.0.8\nCopyright 2006-2016 Christian Stigen Larsen\nDistributed under the GNU General Public License (GPL) v2.\n\nUsage: jp2a [ options ] [ file(s) | URL(s) ]\n\nConvert files or URLs from JPEG format to ASCII.\n");
            return 0;
        } else if (strncmp(argv[i], "--size=", 7) == 0) {
            sscanf(argv[i]+7, "%dx%d", &req_w, &req_h);
            term_fit = 0;
        } else if (strncmp(argv[i], "--width=", 8) == 0) {
            req_w = atoi(argv[i]+8);
            term_fit = 0;
        } else if (strncmp(argv[i], "--height=", 9) == 0) {
            req_h = atoi(argv[i]+9);
            term_fit = 0;
        } else if (strcmp(argv[i], "--term-fit") == 0 || strcmp(argv[i], "-f") == 0) {
            term_fit = 1;
        } else if (strcmp(argv[i], "--term-zoom") == 0 || strcmp(argv[i], "-z") == 0) {
            term_zoom = 1; term_fit = 0;
        } else if (strcmp(argv[i], "--border") == 0 || strcmp(argv[i], "-b") == 0) {
            border = 1;
        } else if (strcmp(argv[i], "--invert") == 0 || strcmp(argv[i], "-i") == 0) {
            invert = 1;
        } else if (strcmp(argv[i], "--background=light") == 0) {
            invert = 0;
        } else if (strcmp(argv[i], "--background=dark") == 0) {
            invert = 1;
        } else if (strcmp(argv[i], "--colors") == 0) {
            colors = 1;
        } else if (strcmp(argv[i], "--html") == 0) {
            html = 1;
        } else if (strncmp(argv[i], "--chars=", 8) == 0) {
            chars = argv[i]+8;
        } else if (strncmp(argv[i], "--red=", 6) == 0) {
            rw = atof(argv[i]+6);
        } else if (strncmp(argv[i], "--green=", 8) == 0) {
            gw = atof(argv[i]+8);
        } else if (strncmp(argv[i], "--blue=", 7) == 0) {
            bw = atof(argv[i]+7);
        } else if (strcmp(argv[i], "--flipx") == 0 || strcmp(argv[i], "-x") == 0) {
            flipx = 1;
        } else if (strcmp(argv[i], "--flipy") == 0 || strcmp(argv[i], "-y") == 0) {
            flipy = 1;
        } else if (strncmp(argv[i], "--term-width=", 13) == 0) {
            term_w_flag = atoi(argv[i]+13);
        } else if (strcmp(argv[i], "--term-width") == 0) {
            term_w_flag = 1;
        } else if (strcmp(argv[i], "--term-height") == 0) {
            term_h_flag = 1;
        } else if (strncmp(argv[i], "--output=", 9) == 0) {
            // Handled above
        } else if (strcmp(argv[i], "-") == 0) {
            process_image(stdin, req_w, req_h, term_fit, term_zoom, border, invert, colors, html, rw, gw, bw, chars, term_w_flag, term_h_flag, flipx, flipy);
        } else if (argv[i][0] != '-') {
            FILE *f = NULL;
            if (strncmp(argv[i], "http://", 7) == 0 || strncmp(argv[i], "https://", 8) == 0) {
                f = tmpfile();
                if(f && c_easy_init) {
                    void *curl = c_easy_init();
                    if(curl) {
                        c_easy_setopt(curl, 10002, argv[i]); // CURLOPT_URL
                        c_easy_setopt(curl, 20011, curl_write_data); // CURLOPT_WRITEFUNCTION
                        c_easy_setopt(curl, 10001, f); // CURLOPT_WRITEDATA
                        c_easy_perform(curl);
                        c_easy_cleanup(curl);
                    }
                    rewind(f);
                }
            } else {
                f = fopen(argv[i], "rb");
            }
            if (f) {
                process_image(f, req_w, req_h, term_fit, term_zoom, border, invert, colors, html, rw, gw, bw, chars, term_w_flag, term_h_flag, flipx, flipy);
                fclose(f);
            }
        }
    }
    return 0;
}
